/** fn pad_of (hop/tests/runs.slg:10): one letter per Pad field, as the game vocabulary reads a script: L R F B J, or - for none */
export function padOf(keys: string): model.Pad {
  return model.Pad.make([
    keys.includes("L"),
    keys.includes("R"),
    keys.includes("F"),
    keys.includes("B"),
    keys.includes("J"),
  ]);
}
